% ============================================================ expression ladder
expr(E) --> lvl_or(E).

% level pow — exponent; one shot (2 ** 3 ** 2 is not folded — not needed here)
lvl_pow(pow(A,B)) --> prim(A), [tok(symbol,'**')], prim(B).
lvl_pow(E) --> prim(E).

% level unary — unary minus; DISTINCT (COUNT(DISTINCT x))
lvl_unary(neg(E)) --> [tok(symbol,'-')], lvl_unary(E).
lvl_unary(distinct(E)) --> [tok(keyword,K)], { downcase_atom(K,'distinct') }, lvl_unary(E).
lvl_unary(E) --> lvl_pow(E).

% level mul
lvl_mul(E) --> lvl_unary(L0), lvl_mul_rest(L0, E).
lvl_mul_rest(L0, E) --> [tok(symbol,'*')], lvl_unary(R), lvl_mul_rest(mul(L0,R), E).
lvl_mul_rest(L0, E) --> [tok(symbol,'/')], lvl_unary(R), lvl_mul_rest(div(L0,R), E).
lvl_mul_rest(E, E) --> [].

% level add
lvl_add(E) --> lvl_mul(L0), lvl_add_rest(L0, E).
lvl_add_rest(L0, E) --> [tok(symbol,'+')], lvl_mul(R), lvl_add_rest(add(L0,R), E).
lvl_add_rest(L0, E) --> [tok(symbol,'-')], lvl_mul(R), lvl_add_rest(sub(L0,R), E).
lvl_add_rest(E, E) --> [].

% level cat — string concatenation
lvl_cat(E) --> lvl_add(L0), lvl_cat_rest(L0, E).
lvl_cat_rest(L0, E) --> [tok(symbol,'||')], lvl_add(R), lvl_cat_rest(cat(L0,R), E).
lvl_cat_rest(E, E) --> [].

% level cmp — comparisons do not chain; `<>` is read as NE (its PROC SQL meaning)
lvl_cmp(eq(A,B)) --> lvl_cat(A), [tok(symbol,'=')], lvl_cat(B).
lvl_cmp(eq(A,B)) --> lvl_cat(A), [tok(keyword,K)], { downcase_atom(K,'eq') }, lvl_cat(B).
lvl_cmp(ne(A,B)) --> lvl_cat(A), [tok(symbol,'^=')], lvl_cat(B).
lvl_cmp(ne(A,B)) --> lvl_cat(A), [tok(symbol,'~=')], lvl_cat(B).
lvl_cmp(ne(A,B)) --> lvl_cat(A), [tok(symbol,'<>')], lvl_cat(B).
lvl_cmp(ne(A,B)) --> lvl_cat(A), [tok(keyword,K)], { downcase_atom(K,'ne') }, lvl_cat(B).
lvl_cmp(lt(A,B)) --> lvl_cat(A), [tok(symbol,'<')], lvl_cat(B).
lvl_cmp(lt(A,B)) --> lvl_cat(A), [tok(keyword,K)], { downcase_atom(K,'lt') }, lvl_cat(B).
lvl_cmp(le(A,B)) --> lvl_cat(A), [tok(symbol,'<=')], lvl_cat(B).
lvl_cmp(le(A,B)) --> lvl_cat(A), [tok(keyword,K)], { downcase_atom(K,'le') }, lvl_cat(B).
lvl_cmp(gt(A,B)) --> lvl_cat(A), [tok(symbol,'>')], lvl_cat(B).
lvl_cmp(gt(A,B)) --> lvl_cat(A), [tok(keyword,K)], { downcase_atom(K,'gt') }, lvl_cat(B).
lvl_cmp(ge(A,B)) --> lvl_cat(A), [tok(symbol,'>=')], lvl_cat(B).
lvl_cmp(ge(A,B)) --> lvl_cat(A), [tok(keyword,K)], { downcase_atom(K,'ge') }, lvl_cat(B).
lvl_cmp(in(A,B)) --> lvl_cat(A), [tok(keyword,K)], { downcase_atom(K,'in') }, [tok(symbol,'(')], args(B), [tok(symbol,')')].
lvl_cmp(E) --> lvl_cat(E).

% level not
lvl_not(not(E)) --> [tok(keyword,K)], { downcase_atom(K,'not') }, lvl_not(E).
lvl_not(E) --> lvl_cmp(E).

% level and
lvl_and(E) --> lvl_not(L0), lvl_and_rest(L0, E).
lvl_and_rest(L0, E) --> [tok(keyword,K)], { downcase_atom(K,'and') }, lvl_not(R), lvl_and_rest(and(L0,R), E).
lvl_and_rest(E, E) --> [].

% level or
lvl_or(E) --> lvl_and(L0), lvl_or_rest(L0, E).
lvl_or_rest(L0, E) --> [tok(keyword,K)], { downcase_atom(K,'or') }, lvl_and(R), lvl_or_rest(or(L0,R), E).
lvl_or_rest(E, E) --> [].

% forms — tried before the bare leaves so a call/qcol/positional
% prefix is matched whole; Prolog backtracking makes the try-then-
% fall-through safe (no lookahead needed).
prim(case_expr(L15,some(Else17))) --> [tok(keyword,K1)], { downcase_atom(K1,'case') }, cl_1(L15), [tok(keyword,K16)], { downcase_atom(K16,'else') }, expr(Else17), [tok(keyword,K18)], { downcase_atom(K18,'end') }.
prim(case_expr(L15,none)) --> [tok(keyword,K1)], { downcase_atom(K1,'case') }, cl_1(L15), [tok(keyword,K18)], { downcase_atom(K18,'end') }.
prim(missing) --> [tok(symbol,'.')].
prim(star(Alias19)) --> [tok(word,Alias19)], [tok(symbol,'.')], [tok(symbol,'*')].
prim(star) --> [tok(symbol,'*')].
prim(paren(E)) --> [tok(symbol,'(')], expr(E), [tok(symbol,')')].
prim(call(N,Args)) --> ( [tok(word,N)] ; [tok(keyword,N)] ), [tok(symbol,'(')], args(Args), [tok(symbol,')')].
prim(col(N,F)) --> [tok(word,N)], [tok(symbol,'.')], [tok(word,F)].
prim(subquery_expr(V)) --> [tok(symbol,'(')], rule_select_core(V), [tok(symbol,')')].

% leaves — token kind == leaf name, by convention (see pydsl_lib.leaf)
prim(lit(N)) --> [tok(number,V)], { atom_number(V,N) }.
prim(lit(S)) --> [tok(string,V)], { unquote_plain(V, S) }.
prim(col(N)) --> [tok(word,N)].

args([A|As]) --> expr(A), args_rest(As).
args([]) --> [].
args_rest([A|As]) --> [tok(symbol,',')], expr(A), args_rest(As).
args_rest([]) --> [].

% ============================================================ print direction
