print_stmt_if_then_set(if_then_set(Var271,Val272,In274), T276) :- print_expr(Val272, 0, T273), print_rule_dsname(In274, T275), flatten([['if'], [Var271], ['='], T273, ['then'], ['set'], T275, [';']], T276).
